<div class="container">
    <header>
        <h1>Yard Sale Table Mapper</h1>
    </header>

    <div class="grid">
        <div class="card no-print">
            <h2>Add New Item</h2>
            <form id="itemForm">
                <div class="form-group">
                    <label for="itemName">Item Description</label>
                    <input type="text" id="itemName" required placeholder="e.g., Vintage Coffee Mug">
                </div>
                <div class="form-group">
                    <label for="itemPrice">Price ($)</label>
                    <input type="number" id="itemPrice" step="0.01" min="0" required placeholder="0.00">
                </div>
                <div class="form-group">
                    <label for="boxNum">Box Number (Optional)</label>
                    <input type="text" id="boxNum" placeholder="e.g., Box 3">
                </div>
                <div class="form-group">
                    <label for="tableZone">Table Placement Zone</label>
                    <select id="tableZone">
                        <option value="left">Left Side</option>
                        <option value="center">Center</option>
                        <option value="right">Right Side</option>
                    </select>
                </div>
                <button type="submit">Add to Table Map</button>
            </form>
            <button class="print-btn" onclick="window.print()">Print Table Map</button>
        </div>

        <div class="card">
            <h2>Table Layout Map</h2>

            <div class="table-visualizer">
                <div class="zone" id="zone-left">
                    <div class="zone-title">Left Side</div>
                    <div class="zone-items"></div>
                </div>
                <div class="zone" id="zone-center">
                    <div class="zone-title">Center</div>
                    <div class="zone-items"></div>
                </div>
                <div class="zone" id="zone-right">
                    <div class="zone-title">Right Side</div>
                    <div class="zone-items"></div>
                </div>
            </div>

            <div class="stats">
                <span>Total Items: <span id="totalItems">0</span></span>
                <span>Estimated Value: $<span id="totalValue">0.00</span></span>
            </div>
        </div>
    </div>
</div>

<script>
    const items = [];
    const form = document.getElementById('itemForm');

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const name = document.getElementById('itemName').value;
        const price = parseFloat(document.getElementById('itemPrice').value);
        const box = document.getElementById('boxNum').value.trim();
        const zone = document.getElementById('tableZone').value;
        const id = Date.now();

        items.push({ id, name, price, box, zone });

        form.reset();
        document.getElementById('itemName').focus();

        renderMap();
    });

    function deleteItem(id) {
        const index = items.findIndex(item => item.id === id);
        if (index !== -1) {
            items.splice(index, 1);
            renderMap();
        }
    }

    function renderMap() {
        // Clear old lists
        document.querySelectorAll('.zone-items').forEach(el => el.innerHTML = '');

        let totalVal = 0;

        items.forEach(item => {
            totalVal += item.price;
            const zoneContainer = document.querySelector(`#zone-${item.zone} .zone-items`);

            const itemEl = document.createElement('div');
            itemEl.className = 'item-tag';

            const boxDisplay = item.box ? ` <small style="color:#64748b;">[${item.box}]</small>` : '';

            itemEl.innerHTML = `
                <div>
                    <strong>${item.name}</strong>${boxDisplay}
                    <div>$${item.price.toFixed(2)}</div>
                </div>
                <button class="delete-btn no-print" onclick="deleteItem(${item.id})">&times;</button>
            `;

            zoneContainer.appendChild(itemEl);
        });

        // Update Summary Data
        document.getElementById('totalItems').textContent = items.length;
        document.getElementById('totalValue').textContent = totalVal.toFixed(2);
    }
</script>

</body>
</html>

