<body>

<div class="container">
    <header>
        <h1>Yard Sale Table Mapper</h1>
    </header>

    <div class="grid">
        <div class="card no-print">
            <h2 id="formHeader">Add New Item</h2>
            <form id="itemForm">
                <input type="hidden" id="itemId">
                <div class="form-group">
                    <label for="itemName">Item Description</label>
                    <input type="text" id="itemName" required placeholder="e.g., Vintage Coffee Mug">
                </div>
                <div class="form-group">
                    <label for="itemPrice">Price ($)</label>
                    <input type="number" id="itemPrice" step="0.01" min="0" required placeholder="0.00">
                </div>
                <div class="form-group">
                    <label for="boxNum">Box Number (Optional)</label>
                    <input type="text" id="boxNum" placeholder="e.g., Box 3">
                </div>
                <div class="form-group">
                    <label for="tableZone">Table Placement Zone</label>
                    <select id="tableZone">
                        <option value="left">Left Side</option>
                        <option value="center">Center</option>
                        <option value="right">Right Side</option>
                    </select>
                </div>
                <div class="btn-container">
                    <button type="submit" id="submitBtn">Add to Table Map</button>
                    <button type="button" id="cancelBtn" class="cancel-btn" onclick="resetFormState()">Cancel</button>
                </div>
            </form>
            <button class="print-btn" onclick="window.print()">Print Table Map</button>
        </div>

        <div class="card">
            <h2>Table Layout Map</h2>

            <div class="table-visualizer">
                <div class="zone" id="zone-left">
                    <div class="zone-title">Left Side</div>
                    <div class="zone-items"></div>
                </div>
                <div class="zone" id="zone-center">
                    <div class="zone-title">Center</div>
                    <div class="zone-items"></div>
                </div>
                <div class="zone" id="zone-right">
                    <div class="zone-title">Right Side</div>
                    <div class="zone-items"></div>
                </div>
            </div>

            <div class="stats">
                <span>Total Items: <span id="totalItems">0</span></span>
                <span>Estimated Value: $<span id="totalValue">0.00</span></span>
            </div>
        </div>
    </div>
</div>

<script>
    const items = [];
    const form = document.getElementById('itemForm');
    const formHeader = document.getElementById('formHeader');
    const submitBtn = document.getElementById('submitBtn');
    const cancelBtn = document.getElementById('cancelBtn');
    const itemIdInput = document.getElementById('itemId');

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const id = itemIdInput.value;
        const name = document.getElementById('itemName').value;
        const price = parseFloat(document.getElementById('itemPrice').value);
        const box = document.getElementById('boxNum').value.trim();
        const zone = document.getElementById('tableZone').value;

        if (id) {
            // Update existing item
            const index = items.findIndex(item => item.id === parseInt(id));
            if (index !== -1) {
                items[index] = { id: parseInt(id), name, price, box, zone };
            }
        } else {
            // Create new item
            items.push({ id: Date.now(), name, price, box, zone });
        }

        resetFormState();
        renderMap();
    });

    function startEdit(id) {
        const item = items.find(item => item.id === id);
        if (!item) return;

        // Populate fields
        itemIdInput.value = item.id;
        document.getElementById('itemName').value = item.name;
        document.getElementById('itemPrice').value = item.price;
        document.getElementById('boxNum').value = item.box;
        document.getElementById('tableZone').value = item.zone;

        // Toggle form styles
        form.classList.add('editing');
        formHeader.textContent = "Edit Item";
        submitBtn.textContent = "Update Item";
        cancelBtn.style.display = "block";

        document.getElementById('itemName').focus();
    }

    function resetFormState() {
        form.reset();
        itemIdInput.value = '';
        form.classList.remove('editing');
        formHeader.textContent = "Add New Item";
        submitBtn.textContent = "Add to Table Map";
        cancelBtn.style.display = "none";
        document.getElementById('itemName').focus();
    }

    function deleteItem(id) {
        const index = items.findIndex(item => item.id === id);
        if (index !== -1) {
            items.splice(index, 1);
            if (itemIdInput.value === id.toString()) {
                resetFormState();
            }
            renderMap();
        }
    }

    function renderMap() {
        document.querySelectorAll('.zone-items').forEach(el => el.innerHTML = '');
        let totalVal = 0;

        items.forEach(item => {
            totalVal += item.price;
            const zoneContainer = document.querySelector(`#zone-${item.zone} .zone-items`);

            const itemEl = document.createElement('div');
            itemEl.className = 'item-tag';

            const boxDisplay = item.box ? ` <small style="color:#64748b;">[${item.box}]</small>` : '';

            itemEl.innerHTML = `
                <div>
                    <strong>${item.name}</strong>${boxDisplay}
                    <div>$${item.price.toFixed(2)}</div>
                </div>
                <div class="item-actions no-print">
                    <button type="button" class="action-btn edit-action" onclick="startEdit(${item.id})">Edit</button>
                    <button type="button" class="action-btn delete-action" onclick="deleteItem(${item.id})">&times;</button>
                </div>
            `;

            zoneContainer.appendChild(itemEl);
        });

        document.getElementById('totalItems').textContent = items.length;
        document.getElementById('totalValue').textContent = totalVal.toFixed(2);
    }
</script>

